":["True"]},{"seed_id":"50000000-0000-0000-0000-000000000080","is_core":false,"syllabus_code":"SL 2.9","type":"numeric_answer","prompt":"A population is modelled by N(t)=800e^(0.12t), where t is in hours. Find N(6), rounded to the nearest whole number.","answer_data":{"answer":1644,"tolerance":0.5},"explanation":"N(6)=800e^0.72≈1643.55, which rounds to 1644.","difficulty":"extension","question_style":"application","calculator":"allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["exponential models","interpretation","application"],"choices":[],"correct_choices":[1644]},{"seed_id":"50000000-0000-0000-0000-000000000081","is_core":true,"syllabus_code":"SL 2.10","type":"numeric_answer","prompt":"Solve 3x−7=11.","answer_data":{"answer":6,"tolerance":0},"explanation":"3x=18, so x=6.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["solving equations","recall"],"choices":[],"correct_choices":[6]},{"seed_id":"50000000-0000-0000-0000-000000000082","is_core":true,"syllabus_code":"SL 2.10","type":"multiple_choice","prompt":"The equation x³+x=1 is best solved in a live quiz using which method?","answer_data":{"answer":"Reading the intersection of y=x³+x and y=1"},"explanation":"The equation has no simple factorization; a graph or numerical solver locates the root.","difficulty":"standard","question_style":"conceptual","calculator":"allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["graphical solutions","conceptual"],"choices":["Factorising by grouping","Reading the intersection of y=x³+x and y=1","Taking square roots","Completing the square"],"correct_choices":["Reading the intersection of y=x³+x and y=1"]},{"seed_id":"50000000-0000-0000-0000-000000000083","is_core":true,"syllabus_code":"SL 2.10","type":"ordering","prompt":"Order the steps for solving 2^(x)=7 using logarithms.","answer_data":{"items":["Divide by ln 2","Take natural logs of both sides","Write x ln 2=ln 7","State x=ln 7/ln 2"],"correctOrder":["Take natural logs of both sides","Write x ln 2=ln 7","Divide by ln 2","State x=ln 7/ln 2"]},"explanation":"Logarithm laws bring the exponent down as a multiplier.","difficulty":"extension","question_style":"procedural","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["exponential equations","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"50000000-0000-0000-0000-000000000084","is_core":true,"syllabus_code":"SL 2.11","type":"multiple_choice","prompt":"The graph y=f(x−4)+2 is obtained from y=f(x) by which translations?","answer_data":{"answer":"4 right and 2 up"},"explanation":"A change inside f acts oppositely on x; +2 outside shifts upward.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["graph transformations","recall"],"choices":["4 left and 2 up","4 right and 2 up","4 right and 2 down","2 right and 4 up"],"correct_choices":["4 right and 2 up"]},{"seed_id":"50000000-0000-0000-0000-000000000085","is_core":true,"syllabus_code":"SL 2.11","type":"multi_select","prompt":"Let y=f(x) contain the point (2,5). Which statements are true for y=3f(x−4)−1?","answer_data":{"answers":["The corresponding point is (6,14).","The graph is translated 4 units right.","The vertical scale factor is 3."]},"explanation":"The x-coordinate becomes 2+4=6 and the y-coordinate becomes 3(5)−1=14.","difficulty":"standard","question_style":"conceptual","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["graph transformations","coordinates","conceptual"],"choices":["The corresponding point is (6,14).","The corresponding point is (−2,14).","The graph is translated 4 units right.","The vertical scale factor is 3."],"correct_choices":["The corresponding point is (6,14).","The graph is translated 4 units right.","The vertical scale factor is 3."]},{"seed_id":"50000000-0000-0000-0000-000000000086","is_core":true,"syllabus_code":"SL 2.11","type":"drag_drop","prompt":"Classify each expression by its transformation of y=f(x).","answer_data":{"zones":["Vertical translation","Horizontal translation","Vertical stretch"],"items":[{"text":"f(x)+4","correctZone":"Vertical translation"},{"text":"f(x−3)","correctZone":"Horizontal translation"},{"text":"2f(x)","correctZone":"Vertical stretch"}]},"explanation":"Changes outside f affect y-values; changes inside f affect x-values.","difficulty":"extension","question_style":"procedural","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["graph transformations","classification","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"50000000-0000-0000-0000-000000000087","is_core":false,"syllabus_code":"SL 2.11","type":"ordering","prompt":"For y=2f(x−3)+4, order these transformations from y=f(x).","answer_data":{"items":["Translate up 4","Translate right 3","Stretch vertically by factor 2"],"correctOrder":["Translate right 3","Stretch vertically by factor 2","Translate up 4"]},"explanation":"The inside change moves right; output values are then doubled and increased by 4.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["graph transformations","order","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"50000000-0000-0000-0000-000000000088","is_core":false,"syllabus_code":"SL 2.11","type":"short_answer","prompt":"The point (1,5) lies on y=f(x). Give its image on y=f(x−2)+3.","answer_data":{"answer":"(3,8)","acceptedAnswers":["(3, 8)","3,8","3, 8"]},"explanation":"Translate 2 right and 3 up, so (1,5) maps to (3,8).","difficulty":"extension","question_style":"exam_style","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["graph transformations","coordinates","exam_style"],"choices":[],"correct_choices":["(3,8)"]},{"seed_id":"50000000-0000-0000-0000-000000000089","is_core":true,"syllabus_code":"AHL 2.12","type":"multiple_choice","prompt":"The polynomial p(x)=x³−4x²+x+6 has x=2 as a root. Which factorisation is correct?","answer_data":{"answer":"(x−2)(x²−2x−3)"},"explanation":"Dividing by x−2 gives x²−2x−3.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["polynomials","factor theorem","recall"],"choices":["(x−2)(x²−2x−3)","(x+2)(x²−6x+3)","(x−2)(x²+2x+3)","(x−3)(x²−x−2)"],"correct_choices":["(x−2)(x²−2x−3)"]},{"seed_id":"50000000-0000-0000-0000-000000000090","is_core":true,"syllabus_code":"AHL 2.12","type":"numeric_answer","prompt":"Find the remainder when p(x)=2x³−x+5 is divided by x−2.","answer_data":{"answer":19,"tolerance":0},"explanation":"By the remainder theorem, the remainder is p(2)=16−2+5=19.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["remainder theorem","procedural"],"choices":[],"correct_choices":[19]},{"seed_id":"50000000-0000-0000-0000-000000000091","is_core":true,"syllabus_code":"AHL 2.12","type":"multi_select","prompt":"A monic cubic has roots 1, 2 and −3. Select all true statements.","answer_data":{"answers":["The sum of the roots is 0.","The product of the roots is −6.","x−1 is a factor."]},"explanation":"The polynomial is (x−1)(x−2)(x+3); its constant term is +6.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["roots","factors","conceptual"],"choices":["The sum of the roots is 0.","The product of the roots is −6.","x−1 is a factor.","Its constant term is −6."],"correct_choices":["The sum of the roots is 0.","The product of the roots is −6.","x−1 is a factor."]},{"seed_id":"50000000-0000-0000-0000-000000000092","is_core":false,"syllabus_code":"AHL 2.12","type":"numeric_answer","prompt":"The polynomial p(x)=x³+ax²−5x+3 has x=1 as a root. Find a.","answer_data":{"answer":1,"tolerance":0},"explanation":"By the factor theorem p(1)=0, so 1+a−5+3=0 and a=1.","difficulty":"extension","question_style":"exam_style","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["polynomials","factor theorem","exam_style"],"choices":[],"correct_choices":[1]},{"seed_id":"50000000-0000-0000-0000-000000000093","is_core":true,"syllabus_code":"AHL 2.13","type":"multiple_choice","prompt":"For f(x)=(x+1)/(x²−4), which values are excluded from the domain?","answer_data":{"answer":"x=±2"},"explanation":"x²−4=(x−2)(x+2), so the denominator is zero at ±2.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["rational functions","domain","recall"],"choices":["x=−1 only","x=±2","x=2 only","x=0 and x=4"],"correct_choices":["x=±2"]},{"seed_id":"50000000-0000-0000-0000-000000000094","is_core":true,"syllabus_code":"AHL 2.13","type":"multiple_choice","prompt":"What is the horizontal asymptote of y=(3x²+1)/(x²−5)?","answer_data":{"answer":"y=3"},"explanation":"The numerator and denominator have equal degree; the leading-coefficient ratio is 3.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["rational functions","asymptotes","procedural"],"choices":["y=0","y=1","y=3","x=3"],"correct_choices":["y=3"]},{"seed_id":"50000000-0000-0000-0000-000000000095","is_core":true,"syllabus_code":"AHL 2.13","type":"true_false","prompt":"The function (x²−1)/(x−1) has a vertical asymptote at x=1.","answer_data":{"answer":false},"explanation":"It simplifies to x+1 for x≠1, so x=1 is a removable hole, not a vertical asymptote.","difficulty":"extension","question_style":"misconception","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["holes","asymptotes","misconception"],"choices":["True","False"],"correct_choices":["False"]},{"seed_id":"50000000-0000-0000-0000-000000000096","is_core":true,"syllabus_code":"AHL 2.14","type":"true_false","prompt":"The function f(x)=x³ is odd.","answer_data":{"answer":true},"explanation":"f(−x)=−x³=−f(x).","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["odd functions","recall"],"choices":["True","False"],"correct_choices":["True"]},{"seed_id":"50000000-0000-0000-0000-000000000097","is_core":true,"syllabus_code":"AHL 2.14","type":"multiple_choice","prompt":"Which domain restriction makes f(x)=x² invertible while keeping non-negative outputs?","answer_data":{"answer":"x≥0 only"},"explanation":"On x≥0 the function is one-to-one and its inverse is √x.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["domain restriction","inverse functions","procedural"],"choices":["x≤0 only","x≥0 only","all real x","x≠0"],"correct_choices":["x≥0 only"]},{"seed_id":"50000000-0000-0000-0000-000000000098","is_core":true,"syllabus_code":"AHL 2.14","type":"multi_select","prompt":"Select all self-inverse functions.","answer_data":{"answers":["f(x)=−x","f(x)=1/x on x≠0"]},"explanation":"Applying −x twice or taking a reciprocal twice returns x.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["self-inverse functions","conceptual"],"choices":["f(x)=−x","f(x)=1/x on x≠0","f(x)=x+2","f(x)=x³"],"correct_choices":["f(x)=−x","f(x)=1/x on x≠0"]},{"seed_id":"50000000-0000-0000-0000-000000000099","is_core":true,"syllabus_code":"AHL 2.15","type":"multiple_choice","prompt":"Solve x²≥4.","answer_data":{"answer":"x≤−2 or x≥2"},"explanation":"The parabola x²−4 is non-negative outside its roots −2 and 2.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["quadratic inequalities","recall"],"choices":["−2≤x≤2","x≤−2 or x≥2","x≥−2","x≤2"],"correct_choices":["x≤−2 or x≥2"]},{"seed_id":"50000000-0000-0000-0000-000000000100","is_core":true,"syllabus_code":"AHL 2.15","type":"multi_select","prompt":"For f(x)=x² and g(x)=2x+3, select every interval on which f(x)≥g(x).","answer_data":{"answers":["x≤−1","x≥3"]},"explanation":"x²−2x−3=(x+1)(x−3) is non-negative outside [−1,3].","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["function inequalities","procedural"],"choices":["x≤−1","−1<x<3","x≥3","0≤x≤2"],"correct_choices":["x≤−1","x≥3"]},{"seed_id":"50000000-0000-0000-0000-000000000101","is_core":true,"syllabus_code":"AHL 2.15","type":"ordering","prompt":"Order the steps for solving (x−1)(x+4)<0.","answer_data":{"items":["Choose the interval where the product is negative","Mark the critical values −4 and 1","Write the solution −4<x<1","Make a sign chart"],"correctOrder":["Mark the critical values −4 and 1","Make a sign chart","Choose the interval where the product is negative","Write the solution −4<x<1"]},"explanation":"Critical values split the number line into intervals with fixed signs.","difficulty":"extension","question_style":"procedural","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["inequalities","sign chart","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"50000000-0000-0000-0000-000000000102","is_core":true,"syllabus_code":"AHL 2.16","type":"multiple_choice","prompt":"Solve |x−3|=5.","answer_data":{"answer":"x=−2 or x=8"},"explanation":"x−3=±5, giving x=8 or x=−2.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["modulus equations","recall"],"choices":["x=8 only","x=−2 only","x=−2 or x=8","x=2 or x=8"],"correct_choices":["x=−2 or x=8"]},{"seed_id":"50000000-0000-0000-0000-000000000103","is_core":true,"syllabus_code":"AHL 2.16","type":"multi_selec