":"180°"}]},"explanation":"In radian measure, s=rθ and A=½r²θ.","difficulty":"standard","question_style":"conceptual","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["radians","formulae","conceptual"],"choices":[],"correct_choices":[]},{"seed_id":"50000000-0000-0000-0000-000000000118","is_core":false,"syllabus_code":"SL 3.4","type":"multiple_choice","prompt":"A wheel of radius 0.4 m turns through 15 radians. How far does a point on its rim travel?","answer_data":{"answer":"6 m"},"explanation":"Arc length s=rθ=0.4(15)=6 m.","difficulty":"extension","question_style":"application","calculator":"allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["radians","arc length","application"],"choices":["3.75 m","6 m","15.4 m","37.5 m"],"correct_choices":["6 m"]},{"seed_id":"50000000-0000-0000-0000-000000000119","is_core":true,"syllabus_code":"SL 3.5","type":"multiple_choice","prompt":"Find the exact value of sin(π/6).","answer_data":{"answer":"1/2"},"explanation":"The unit-circle point at π/6 has y-coordinate 1/2.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["unit circle","exact values","recall"],"choices":["0","1/2","√2/2","√3/2"],"correct_choices":["1/2"]},{"seed_id":"50000000-0000-0000-0000-000000000120","is_core":true,"syllabus_code":"SL 3.5","type":"multi_select","prompt":"Select all angles θ in 0≤θ≤2π for which cosθ=0.","answer_data":{"answers":["π/2","3π/2"]},"explanation":"Cosine is the x-coordinate on the unit circle and is zero on the vertical axis.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["unit circle","cosine","procedural"],"choices":["0","π/2","π","3π/2"],"correct_choices":["π/2","3π/2"]},{"seed_id":"50000000-0000-0000-0000-000000000121","is_core":true,"syllabus_code":"SL 3.5","type":"true_false","prompt":"Using the sine rule with two sides and a non-included angle can sometimes produce two possible triangles.","answer_data":{"answer":true},"explanation":"The ambiguous case occurs because sinθ=sin(π−θ).","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["ambiguous case","sine rule","conceptual"],"choices":["True","False"],"correct_choices":["True"]},{"seed_id":"50000000-0000-0000-0000-000000000122","is_core":true,"syllabus_code":"SL 3.6","type":"fill_blank","prompt":"Complete the identity: sin²θ+cos²θ=___.","answer_data":{"answer":"1","acceptedAnswers":["1"]},"explanation":"This is the fundamental Pythagorean identity.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["trigonometric identities","recall"],"choices":[],"correct_choices":["1"]},{"seed_id":"50000000-0000-0000-0000-000000000123","is_core":true,"syllabus_code":"SL 3.6","type":"multiple_choice","prompt":"Which expression is equal to sin(2θ)?","answer_data":{"answer":"2sinθ cosθ"},"explanation":"The sine double-angle identity is sin2θ=2sinθcosθ.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["double-angle identities","procedural"],"choices":["2sinθ cosθ","sin²θ−cos²θ","2sinθ","sinθ+cosθ"],"correct_choices":["2sinθ cosθ"]},{"seed_id":"50000000-0000-0000-0000-000000000124","is_core":true,"syllabus_code":"SL 3.6","type":"multiple_choice","prompt":"If tanθ=3/4 and θ is acute, find sinθ.","answer_data":{"answer":"3/5"},"explanation":"A 3-4-5 triangle gives opposite/hypotenuse=3/5.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["trigonometric ratios","identity","conceptual"],"choices":["3/4","4/5","3/5","5/3"],"correct_choices":["3/5"]},{"seed_id":"50000000-0000-0000-0000-000000000125","is_core":true,"sylla