iven P(A∩B)=0.18 and P(B)=0.30, find P(A|B).","answer_data":{"answer":0.6,"tolerance":0},"explanation":"P(A|B)=0.18/0.30=0.6.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["conditional probability","procedural"],"choices":[],"correct_choices":[0.6]},{"seed_id":"50000000-0000-0000-0000-000000000181","is_core":true,"syllabus_code":"SL 4.6","type":"multi_select","prompt":"P(A)=0.4, P(B)=0.5 and P(A∩B)=0.2. Select all true statements.","answer_data":{"answers":["A and B are independent.","P(A∪B)=0.7.","P(A|B)=0.4."]},"explanation":"P(A)P(B)=0.2, the union is 0.7, and P(A|B)=0.2/0.5=0.4.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["independence","conditional probability","conceptual"],"choices":["A and B are independent.","A and B are mutually exclusive.","P(A∪B)=0.7.","P(A|B)=0.4."],"correct_choices":["A and B are independent.","P(A∪B)=0.7.","P(A|B)=0.4."]},{"seed_id":"50000000-0000-0000-0000-000000000182","is_core":false,"syllabus_code":"SL 4.6","type":"matching","prompt":"Match each probability expression to its interpretation.","answer_data":{"pairs":[{"left":"P(A∩B)","right":"A and B both occur"},{"left":"P(A∪B)","right":"A or B or both occur"},{"left":"P(A|B)","right":"A occurs given B"}]},"explanation":"Intersection means both, union means at least one, and the vertical bar means given.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["probability notation","recall"],"choices":[],"correct_choices":[]},{"seed_id":"50000000-0000-0000-0000-000000000183","is_core":false,"syllabus_code":"SL 4.6","type":"numeric_answer","prompt":"A bag contains 3 red and 2 blue counters. Two are drawn without replacement. Find the probability both are red.","answer_data":{"answer":0.3,"tolerance":0.001},"explanation":"P(RR)=