tension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["unknown mean","z-scores","conceptual"],"choices":[],"correct_choices":[22]},{"seed_id":"50000000-0000-0000-0000-000000000202","is_core":true,"syllabus_code":"AHL 4.13","type":"multiple_choice","prompt":"A disease affects 1% of people. A test is 90% sensitive and has a 5% false-positive rate. Which information is needed for P(disease|positive)?","answer_data":{"answer":"Bayes’ theorem using both positive pathways"},"explanation":"The posterior compares true positives with all positive results.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["Bayes theorem","recall"],"choices":["Bayes’ theorem using both positive pathways","Only the sensitivity","Only the prevalence","The sample mean"],"correct_choices":["Bayes’ theorem using both positive pathways"]},{"seed_id":"50000000-0000-0000-0000-000000000203","is_core":true,"syllabus_code":"AHL 4.13","type":"numeric_answer","prompt":"Machines A and B make 60% and 40% of items. Their defect rates are 2% and 5%. Find P(B|defect).","answer_data":{"answer":0.625,"tolerance":0.001},"explanation":"P(B|D)=0.4(0.05)/[0.6(0.02)+0.4(0.05)]=0.02/0.032=0.625.","difficulty":"standard","question_style":"application","calculator":"allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["Bayes theorem","conditional probability","application"],"choices":[],"correct_choices":[0.625]},{"seed_id":"50000000-0000-0000-0000-000000000204","is_core":true,"syllabus_code":"AHL 4.13","type":"ordering","prompt":"Order the steps in a Bayes calculation.","answer_data":{"items":["Divide the chosen joint probability by the total evidence probability","Compute each pathway joint probability","Identify the prior and conditional probabilities","Add pathways that produce the evidence"],"correctOrder":["Identify the prior and conditional probabilities","Compute each pathway joint probability","Add pathways that produce the evidence","Divide the chosen joint probability by the total evidence probability"]},"explanation":"Bayes’ theorem normalizes the desired pathway by all pathways producing the evidence.","difficulty":"extension","question_style":"procedural","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["Bayes theorem","method","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"50000000-0000-0000-0000-000000000205","is_core":true,"syllabus_code":"AHL 4.14","type":"numeric_answer","prompt":"A continuous density is f(x)=kx on 0≤x≤2 and 0 otherwise. Find k.","answer_data":{"answer":0.5,"tolerance":0},"explanation":"Total area is ∫₀²kx dx=2k=1, so k=0.5.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["probability density functions","recall"],"choices":[],"correct_choices":[0.5]},{"seed_id":"50000000-0000-0000-0000-000000000206","is_core":true,"syllabus_code":"AHL 4.14","type":"multiple_choice","prompt":"For a continuous random variable X, what is P(X=3)?","answer_data":{"answer":"0"},"explanation":"A single point has zero area under a continuous density.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["continuous random variables","procedural"],"choices":["0","f(3)","1","Cannot be determined"],"correct_choices":["0"]},{"seed_id":"50000000-0000-0000-0000-000000000207","is_core":true,"syllabus_code":"AHL 4.14","type":"numeric_answer","prompt":"If E(X)=4 and Var(X)=9, find Var(2X−5).","answer_data":{"answer":36,"tolerance":0},"explanation":"Var(aX+b)=a²Var(X), so Var(2X−5)=4(9)=36.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["variance","linear transformations","conceptual"],"choices":[],"correct_choices":[36]},{"seed_i