e no function value.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["limits","continuity","conceptual"],"choices":["True","False"],"correct_choices":["True"]},{"seed_id":"50000000-0000-0000-0000-000000000212","is_core":true,"syllabus_code":"SL 5.2","type":"multiple_choice","prompt":"If f′(x)>0 throughout an interval, what is f doing there?","answer_data":{"answer":"Increasing"},"explanation":"A positive derivative means positive local gradient.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["increasing functions","derivative sign","recall"],"choices":["Increasing","Decreasing","Constant","Undefined"],"correct_choices":["Increasing"]},{"seed_id":"50000000-0000-0000-0000-000000000213","is_core":true,"syllabus_code":"SL 5.2","type":"multi_select","prompt":"A graph of f′ crosses from positive to negative at x=2. Select all valid conclusions.","answer_data":{"answers":["f has a local maximum at x=2.","f is increasing just before x=2.","f is decreasing just after x=2."]},"explanation":"The sign change + to − makes f rise then fall.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["stationary points","derivative sign","procedural"],"choices":["f has a local maximum at x=2.","f is increasing just before x=2.","f is decreasing just after x=2.","f has a local minimum at x=2."],"correct_choices":["f has a local maximum at x=2.","f is increasing just before x=2.","f is decreasing just after x=2."]},{"seed_id":"50000000-0000-0000-0000-000000000214","is_core":true,"syllabus_code":"SL 5.2","type":"true_false","prompt":"If f′(a)=0, then f must have a local maximum or minimum at x=a.","answer_data":{"answer":false},"explanation":"A stationary point can be an inflexion, such as f(x)=x³ at x=0.","difficulty":"extension","quest