 be applied directly to any quotient limit, including one whose substitution gives 2/3.","answer_data":{"answer":false},"explanation":"It is intended for indeterminate forms such as 0/0 or ∞/∞.","difficulty":"extension","question_style":"misconception","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["L’Hopital rule","indeterminate forms","misconception"],"choices":["True","False"],"correct_choices":["False"]},{"seed_id":"50000000-0000-0000-0000-000000000251","is_core":true,"syllabus_code":"AHL 5.14","type":"short_answer","prompt":"For x²+y²=25, find dy/dx.","answer_data":{"answer":"−x/y","acceptedAnswers":["-x/y","−x/y","-(x/y)"]},"explanation":"Implicit differentiation gives 2x+2y(dy/dx)=0.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["implicit differentiation","recall"],"choices":[],"correct_choices":["−x/y"]},{"seed_id":"50000000-0000-0000-0000-000000000252","is_core":true,"syllabus_code":"AHL 5.14","type":"numeric_answer","prompt":"A circle’s radius increases at 2 cm/s. Find dA/dt when r=3 cm, in terms of π by entering the coefficient of π.","answer_data":{"answer":12,"tolerance":0},"explanation":"A=πr², so dA/dt=2πr(dr/dt)=12π.","difficulty":"standard","question_style":"application","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["related rates","application"],"choices":[],"correct_choices":[12]},{"seed_id":"50000000-0000-0000-0000-000000000253","is_core":true,"syllabus_code":"AHL 5.14","type":"multiple_choice","prompt":"At the point (3,4) on x²+y²=25, what is the tangent gradient?","answer_data":{"answer":"−3/4"},"explanation":"dy/dx=−x/y=−3/4.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["implicit differentiation","tangent","conceptual"],"choices":["−4/3","−3/4","3/4","4/3"],"correct_choices":["−3/4"]},{"seed_id":"50000000-0000-0000-0000-000000000254","is_core":true,"syllabus_code":"AHL 5.15","type":"multiple_choice","prompt":"Differentiate y=arctan x.","answer_data":{"answer":"1/(1+x²)"},"explanation":"This is the standard derivative of arctan x.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["inverse trigonometric derivatives","recall"],"choices":["1/(1+x²)","−1/(1+x²)","1/√(1−x²)","sec²x"],"correct_choices":["1/(1+x²)"]},{"seed_id":"50000000-0000-0000-0000-000000000255","is_core":true,"syllabus_code":"AHL 5.15","type":"short_answer","prompt":"Differentiate y=x ln x.","answer_data":{"answer":"lnx+1","acceptedAnswers":["ln x + 1","ln(x)+1","1+lnx"]},"explanation":"The product rule gives 1·lnx+x(1/x)=lnx+1.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["logarithmic derivatives","product rule","procedural"],"choices":[],"correct_choices":["lnx+1"]},{"seed_id":"50000000-0000-0000-0000-000000000256","is_core":true,"syllabus_code":"AHL 5.15","type":"multiple_choice","prompt":"Evaluate ∫1/(1+x²) dx.","answer_data":{"answer":"arctanx+C"},"explanation":"The derivative of arctanx is 1/(1+x²).","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["inverse trigonometric integrals","conceptual"],"choices":["ln|1+x²|+C","arctanx+C","arcsinx+C","−1/(1+x)+C"],"correct_choices":["arctanx+C"]},{"seed_id":"50000000-0000-0000-0000-000000000257","is_core":true,"syllabus_code":"AHL 5.16","type":"multiple_choice","prompt":"Which method is most direct for ∫x eˣ dx?","answer_data":{"answer":"Integration by parts"},"explanation":"The integrand is a product of an algebraic and exponential factor.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["integration by parts","recall"],"choices":["Integration by parts","Partial fractions","Trigonometric substitution","Long division"],"correct_choices":["Integration by parts"]},{"seed_id":"50000000-0000-0000-0000-000000000258","is_core":true,"syllabus_code":"AHL 5.16","type":"short_answer","prompt":"Evaluate ∫2x cos(x²) dx.","answer_data":{"answer":"sin(x²)+C","acceptedAnswers":["sin(x^2)+C","sin(x²) + C","sin(x²)+C"]},"explanation":"Let u=x², so du=2x dx.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["integration by substitution","procedural"],"choices":[],"correct_choices":["sin(x²)+C"]},{"seed_id":"50000000-0000-0000-0000-000000000259","is_core":true,"syllabus_code":"AHL 5.16","type":"ordering","prompt":"Order the steps for integration by parts.","answer_data":{"items":["Substitute into ∫u dv=uv−∫v du","Choose u and dv","Integrate dv to find v","Differentiate u to find du"],"correctOrder":["Choose u and dv","Differentiate u to find du","Integrate dv to find v","Substitute into ∫u dv=uv−∫v du"]},"explanation":"Choose factors, form du and v, then apply the formula.","difficulty":"extension","question_style":"procedural","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["integration by parts","method","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"50000000-0000-0000-0000-000000000260","is_core":true,"syllabus_code":"AHL 5.17","type":"numeric_answer","prompt":"The region under y=x from x=0 to x=2 is revolved about the x-axis. Find the volume as a coefficient of π.","answer_data":{"answer":2.666667,"tolerance":0.00001},"explanation":"V=π∫₀²x²dx=8π/3.","difficulty":"foundation","question_style":"application","calculator":"allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["volume of revolution","application"],"choices":[],"correct_choices":[2.666667]},{"seed_id":"50000000-0000-0000-0000-000000000261","is_core":true,"syllabus_code":"AHL 5.17","type":"multiple_choice","prompt":"To find the area between x=y² and x=2y for 0≤y≤2, which integral is correct?","answer_data":{"answer":"∫₀²(2y−y²)dy"},"explanation":"Against the y-axis, integrate right x minus left x with respect to y.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["area against y-axis","procedural"],"choices":["∫₀²(2y−y²)dy","∫₀²(y²−2y)dy","∫₀²(2y−y²)dx","∫₀²(y−y²)dy"],"correct_choices":["∫₀²(2y−y²)dy"]},{"seed_id":"50000000-0000-0000-0000-000000000262","is_core":true,"syllabus_code":"AHL 5.17","type":"true_false","prompt":"When a region is revolved about the y-axis and x is given as a function of y, the disc method uses V=π∫x² dy.","answer_data":{"answer":true},"explanation":"The radius is the horizontal distance x from the y-axis.","difficulty":"extension","question_style":"conceptual","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["volume of revolution","conceptual"],"choices":["True","False"],"correct_choices":["True"]},{"seed_id":"50000000-0000-0000-0000-000000000263","is_core":true,"syllabus_code":"AHL 5.18","type":"multiple_choice","prompt":"Solve dy/dx=3y by separation. Which general solution is correct?","answer_data":{"answer":"y=Ce^(3x)"},"explanation":"dy/y=3dx gives lny=3x+C and hence y=Ce^(3x).","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["differential equations","separation","recall"],"choices":["y=3x+C","y=Ce^(3x)","y=Cx³","y=e^x+3"],"correct_choices":["y=Ce^(3x)"]},{"seed_id":"50000000-0000-0000-0000-000000000264","is_core":true,"syllabus_code":"AHL 5.18","type":"numeric_answer","prompt":"Euler’s method uses yₙ₊₁=yₙ+h f(xₙ,yₙ). If y₀=1, h=0.1 and f=2y, find y₁.","answer_data":{"answer":1.2,"tolerance":0},"explanation":"y₁=1+0.1(2·1)=1.2.","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["Euler method","procedural"],"choices":[],"correct_choices":[1.2]},{"seed_id":"50000000-0000-0000-0000-000000000265","is_core":true,"syllabus_code":"AHL 5.18","type":"ordering","prompt":"Order the steps for solving a first-order linear differential equation y′+P(x)y=Q(x).","answer_data":{"items":["Multiply through by the integrating factor","Integrate both sides","Find μ=e^(∫P dx)","Recognize the left side as (μy)′"],"correctOrder":["Find μ=e^(∫P dx)","Multiply through by the integrating factor","Recognize the left side as (μy)′","Integrate both sides"]},"explanation":"The integrating factor converts the left side to a product derivative.","difficulty":"extension","question_style":"procedural","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["integrating factors","procedural"],"choices":[],"correct_choices":[]},{"seed_id":"50000000-0000-0000-0000-000000000266","is_core":false,"syllabus_code":"AHL 5.18","type":"numeric_answer","prompt":"A quantity satisfies dy/dx=−0.4y with y(0)=100. Find y(5), correct to three decimal places.","answer_data":{"answer":13.534,"tolerance":0.001},"explanation":"The solution is y=100e^(−0.4x), so y(5)=100e^(−2)≈13.534.","difficulty":"extension","question_style":"application","calculator":"allowed","estimated_time_seconds":75,"marks_estimate":3,"tags":["differential equations","exponential decay","application"],"choices":[],"correct_choices":[13.534]},{"seed_id":"50000000-0000-0000-0000-000000000267","is_core":true,"syllabus_code":"AHL 5.19","type":"multiple_choice","prompt":"Which is the Maclaurin expansion of eˣ up to x³?","answer_data":{"answer":"1+x+x²/2+x³/6"},"explanation":"eˣ=Σxⁿ/n!.","difficulty":"foundation","question_style":"recall","calculator":"not_allowed","estimated_time_seconds":35,"marks_estimate":1,"tags":["Maclaurin series","recall"],"choices":["1+x+x²/2+x³/6","1−x+x²−x³","x−x³/6","1+x²/2"],"correct_choices":["1+x+x²/2+x³/6"]},{"seed_id":"50000000-0000-0000-0000-000000000268","is_core":true,"syllabus_code":"AHL 5.19","type":"fill_blank","prompt":"Complete the Maclaurin expansion: sinx=x−___+… .","answer_data":{"answer":"x³/6","acceptedAnswers":["x^3/6","x³/6","(x³)/6"]},"explanation":"sinx=x−x³/3!+x⁵/5!−… .","difficulty":"standard","question_style":"procedural","calculator":"not_allowed","estimated_time_seconds":60,"marks_estimate":2,"tags":["Maclaurin series","sine","procedural"],"choices":[],"correct_choices":["x³/6"]},{"seed_id":"50000000-0000-0000-0000-000000000269","is_core":true,"syllabus_code":"AHL 5.19","type":"numeric_answer","prompt":"Using 1/(1−x)=1+x+x²+…, approximate 1/0.9 with terms through x² by setting x=0.1.","answer_data":{"answer":1.11,"tolerance":0.001},"explanation":"1+0.1+0.01=1.11.","difficulty":"extension","question_style":"application","calculator":"neutral","estimated_time_seconds":75,"marks_estimate":2,"tags":["Maclaurin series","approximation","application"],"choices":[],"correct_choices":[1.11]}]$mathpulse_seed$::jsonb) as x(
  seed_id uuid,is_core boolean,syllabus_code text,type text,prompt text,answer_data jsonb,
  explanation text,difficulty text,question_style text,calculator text,
  estimated_time_seconds integer,marks_estimate integer,tags jsonb,choices jsonb,correct_choices jsonb
)
join public.syllabus_points sp on upper(sp.code)=upper(x.syllabus_code)
join public.courses c on c.id=sp.course_id and c.slug like 'ib-mathematics-aa%';

update public.questions q set
  owner_type='platform',visibility='public',status='approved',course_id=s.course_id,
  type=s.type::public.question_type,prompt=s.prompt,answer_data=s.answer_data,
  explanation=s.explanation,difficulty=s.difficulty::public.question_difficulty,
  question_style=s.question_style::public.question_style,calculator=s.calculator::public.calculator_mode,
  estimated_time_seconds=s.estimated_time_seconds,marks_estimate=s.marks_estimate,
  tags=array(select jsonb_array_elements_text(s.tags)),updated_at='2026-07-23T00:00:00Z'
from _mathpulse_aa_seed s
where s.is_core and q.syllabus_point_id=s.syllabus_point_id
  and q.difficulty=s.difficulty::public.question_difficulty and q.source='platform_seed'
  and (lower(q.prompt) like '%mapped to syllabus point%' or lower(q.prompt) like '%accurately describe sl %'
    or lower(q.prompt) like '%accurately describe ahl %' or lower(q.prompt) like 'true or false: sl % includes %'
    or lower(q.prompt) like 'true or false: ahl % includes %' or lower(q.prompt) like '%correct syllabus code%'
    or lower(q.prompt) like '%should be tagged%' or lower(q.prompt) like '%work focused on%');

insert into public.questions(id,created_by,owner_type,visibility,status,course_id,syllabus_point_id,type,prompt,answer_data,explanation,difficulty,question_style,calculator,estimated_time_seconds,marks_estimate,tags,source,created_at,updated_at)
select s.seed_id,null,'platform','public','approved',s.course_id,s.syllabus_point_id,
  s.type::public.question_type,s.prompt,s.answer_data,s.explanation,s.difficulty::public.question_difficulty,
  s.question_style::public.question_style,s.calculator::public.calculator_mode,
  s.estimated_time_seconds,s.marks_estimate,array(select jsonb_array_elements_text(s.tags)),
  'platform_seed','2026-07-23T00:00:00Z','2026-07-23T00:00:00Z'
from _mathpulse_aa_seed s
where not exists(select 1 from public.questions q where q.syllabus_point_id=s.syllabus_point_id and q.prompt=s.prompt)
on conflict(id) do update set
  syllabus_point_id=excluded.syllabus_point_id,type=excluded.type,prompt=excluded.prompt,
  answer_data=excluded.answer_data,explanation=excluded.explanation,difficulty=excluded.difficulty,
  question_style=excluded.question_style,calculator=excluded.calculator,
  estimated_time_seconds=excluded.estimated_time_seconds,marks_estimate=excluded.marks_estimate,
  tags=excluded.tags,updated_at=excluded.updated_at;

delete from public.question_options qo using public.questions q,_mathpulse_aa_seed s
where qo.question_id=q.id and q.syllabus_point_id=s.syllabus_point_id and q.prompt=s.prompt;

insert into public.question_options(question_id,label,text,is_correct,sort_order)
select q.id,chr(64+choice.ordinality::integer),choice.text,s.correct_choices ? choice.text,(choice.ordinality-1)::integer
from _mathpulse_aa_seed s
join public.questions q on q.syllabus_point_id=s.syllabus_point_id and q.prompt=s.prompt
cross join lateral jsonb_array_elements_text(s.choices) with ordinality as choice(text,ordinality);

do $$ begin
  if exists(select 1 from public.questions q where q.source='platform_seed' and (
    lower(q.prompt) like '%mapped to syllabus point%' or lower(q.prompt) like '%accurately describe sl %'
    or lower(q.prompt) like '%accurately describe ahl %' or lower(q.prompt) like '%correct syllabus code%'
    or lower(q.prompt) like '%should be tagged%' or lower(q.prompt) like '%work focused on%')) then
    raise exception 'Legacy metadata question replacement was incomplete';
  end if;
end $$;

commit;
